package es.jvbabi.overmail.ui.components.orb

import kotlin.math.abs
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * The port against the frames of the original: thinking-orbs 0.3.1's `spec/orbs-golden.json`, the cases of
 * the states ported here, at the inline size the app draws them in. Dots are in draw order, six numbers each: x, y, z, r, white, a.
 */
class OrbEngineTest {
    private class GoldenCase(val state: OrbState, val size: OrbSize, val t: Double, val dots: DoubleArray)

    @Test
    fun framesMatchTheOriginal() {
        for (case in CASES) {
            val frame = resolveOrb(case.state, case.size).frame(case.size.px.toDouble(), case.t)
            val name = "${case.state} ${case.size} at ${case.t}"
            assertEquals(case.dots.size / 6, frame.size, "dot count of $name")
            frame.forEachIndexed { index, dot ->
                val expected = case.dots.copyOfRange(index * 6, index * 6 + 6)
                val actual = doubleArrayOf(dot.x, dot.y, dot.z, dot.r, dot.white, dot.a)
                expected.indices.forEach { i ->
                    assertTrue(abs(expected[i] - actual[i]) < TOLERANCE, "dot $index of $name: ${actual.toList()} != ${expected.toList()}")
                }
            }
        }
    }

